func SignupFamilyAcceptance(catalogs []*Catalog) ([]*Catalog, error) {
	want := map[string]bool{}
	for _, id := range RequiredSignupFamilyScenarios {
		want[id] = false
	}
	var selected []*Catalog
	for _, c := range catalogs {
		copy := *c
		copy.Rows = nil
		for _, r := range c.Rows {
			picked := r
			picked.Scenarios = nil
			for _, scenario := range r.Scenarios {
				seen, ok := want[scenario.ID]
				if !ok {
					continue
				}
				if seen {
					return nil, fmt.Errorf("duplicate required scenario %s", scenario.ID)
				}
				if r.Listener != listenerAPI || r.Method != http.MethodPost || r.Path != "/api/v1/auth/signup" {
					return nil, fmt.Errorf("%s: changed signup route", scenario.ID)
				}
				if err := ValidatePairing(scenario.V2Expectation); err != nil {
					return nil, fmt.Errorf("%s: %w", scenario.ID, err)
				}
				want[scenario.ID] = true
				picked.Scenarios = append(picked.Scenarios, scenario)
			}
			if len(picked.Scenarios) > 0 {
				copy.Rows = append(copy.Rows, picked)
			}
		}
		if len(copy.Rows) > 0 {
			selected = append(selected, &copy)
		}
	}
	for _, id := range RequiredSignupFamilyScenarios {
		if !want[id] {
			return nil, fmt.Errorf("required scenario %s is missing", id)
		}
	}
	var specs map[string]any
	if err := json.Unmarshal([]byte(signupFamilySpecs), &specs); err != nil {
		return nil, err
	}
	for _, c := range selected {
		for _, r := range c.Rows {
			for _, s := range r.Scenarios {
				if (r.RegistrationIndex == 1) != strings.HasSuffix(s.ID, ".r1") || r.RegistrationIndex < 0 || r.RegistrationIndex > 1 {
					return nil, fmt.Errorf("%s: changed registration", s.ID)
				}
				raw, err := json.Marshal(s)
				if err != nil {
					return nil, err
				}
				var got any
				if err := json.Unmarshal(raw, &got); err != nil {
					return nil, err
				}
				if !reflect.DeepEqual(got, specs[s.ID]) {
					return nil, fmt.Errorf("%s: changed original or signup exchange", s.ID)
				}
			}
		}
	}
	return selected, nil
}
